function expert_form(string $operation,int $id): void {echo '<form data-api="seo-expert-admin" method="post" action="'.url('/api/v1/seo-expert-admin').'">';csrf_field();echo '<input type="hidden" name="operation" value="'.e($operation).'"><input type="hidden" name="id" value="'.$id.'">';}
function expert_text(string $key,string $label,string $value='',bool $required=true): void {echo '<label>'.e($label).'<textarea name="'.e($key).'" rows="3" '.($required?'required':'').'>'.e($value).'</textarea></label>';}
function expert_contact(array $lead): void {$digits=preg_replace('/\D/','',$lead['phone']);echo '<div class="expert-actions"><a class="button secondary" href="tel:'.e($lead['phone']).'">Call client</a><a class="button secondary" href="https://wa.me/'.$digits.'" target="_blank" rel="noopener">WhatsApp client</a><a class="button secondary" href="mailto:'.e($lead['email']).'">Email client</a></div>';}
