<link rel="stylesheet" href="<?=url('/assets/css/seo-expert.css')?>">
<section class="expert-admin"><div class="page-heading"><div><span class="eyebrow">PREMIUM SEO SERVICES</span><h2>SEO Expert Leads Dashboard</h2><p>A dedicated workspace for enquiries, clients and measurable progress.</p></div><a class="button secondary" href="<?=url('/admin/seo-expert')?>">All enquiries</a></div>
<?php if(isset($_GET['client'])): $clientId=filter_var($_GET['client'],FILTER_VALIDATE_INT);if(!$clientId||$clientId<1)fail('Invalid client.',400);$client=SeoExpert::client($clientId);require ROOT.'/admin/seo-expert-client.php';
